#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""מקור התוכן לבקיאות: מסכת תענית ב ע"א – ח ע"ב.
כל "מי אמר" וכל נקודה בסיכום מסומנים במקור (amud:segment) ובמחרוזת שחייבת להופיע בטקסט של ספריא באותו קטע.
הסקריפט נכשל אם מחרוזת לא נמצאה – כך שלא ניתן לייחס דבר לאמורא שלא אמר אותו.
גם טקסט הגמרא המלא לכל עמוד נכתב (data/taanit_text.json), אחרי החלפת שמות קדושים (tools/names.py).
  python3 tools/taanit_source.py"""
import json, os, re, sys, unicodedata
sys.path.insert(0, os.path.dirname(__file__))
import names
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
SRC = json.load(open(os.path.join(ROOT, 'tools/sefaria/all.json'), encoding='utf-8'))
NQ = re.compile(r'[\u0591-\u05C7]')
def clean(s): return unicodedata.normalize('NFC', re.sub(r'<[^>]+>', '', s)).replace('\u00a0', ' ').strip()
def plain(s): return re.sub(r'\s+', ' ', re.sub(r'[:,.;?!]', '', NQ.sub('', clean(s))).replace('—', ' ').replace('–', ' ').replace('״', '').replace('׳', "'"))
def segtext(ref):
    a, n = ref.split(':'); return SRC['Taanit.' + a]['gemara'][int(n) - 1]
HEB = {2: 'ב', 3: 'ג', 4: 'ד', 5: 'ה', 6: 'ו', 7: 'ז', 8: 'ח'}
def dafname(a): return HEB[int(a[:-1])] + ' ע"' + ('א' if a[-1] == 'a' else 'ב')

A = []
def amud(id, title, topics, summary, who, quiz):
    A.append({'id': id, 'title': title, 'topics': topics, 'summary': summary, 'who': who, 'quiz': quiz})
def S(ref, t, needle=None): return {'ref': ref, 't': t, 'n': needle}
def W(ref, who, said, needle): return {'ref': ref, 'who': who, 'said': said, 'n': needle}
def Q(q, o, a, ex, ref): return {'q': q, 'o': o, 'a': a, 'ex': ex, 'ref': ref}

