def build():
    out, texts, errs = [], {}, []
    for a in A:
        segs = SRC['Taanit.' + a['id']]['gemara']
        def check(ref, needle, what):
            am, n = ref.split(':')
            t = plain(SRC['Taanit.' + am]['gemara'][int(n) - 1])
            if needle and plain(needle) not in t:
                errs.append(f'{a["id"]} {what} {ref}: "{needle}" not found in: {t[:160]}')
        for s in a['summary']: check(s['ref'], s['n'], 'summary')
        for w in a['who']: check(w['ref'], w['n'], 'who:' + w['who'])
        for q in a['quiz']:
            am, n = q['ref'].split(':'); assert 1 <= int(n) <= len(SRC['Taanit.' + am]['gemara']), q['ref']
            assert len(q['o']) == 4
        log = []
        texts[a['id']] = [names.fix(clean(g), log) for g in segs]
        out.append({'id': a['id'], 'daf': dafname(a['id']), 'title': a['title'], 'topics': a['topics'],
                    'summary': [{'ref': s['ref'], 't': s['t']} for s in a['summary']],
                    'who': [{'ref': w['ref'], 'who': w['who'], 'said': w['said']} for w in a['who']],
                    'quiz': [{'id': a['id'] + 'q%d' % i, **q} for i, q in enumerate(a['quiz'], 1)]})
    if errs:
        print('\n'.join(errs)); sys.exit(1)
    return out, texts
if __name__ == '__main__':
    amudim, texts = build()
    json.dump({'title': 'מסכת תענית · ב ע"א – ח ע"ב', 'source': 'ספריא: William Davidson Edition – Vocalized Aramaic; ביאור על פי שטיינזלץ', 'amudim': amudim},
              open(os.path.join(ROOT, 'data/taanit.json'), 'w', encoding='utf-8'), ensure_ascii=False, separators=(',', ':'))
    json.dump(texts, open(os.path.join(ROOT, 'data/taanit_text.json'), 'w', encoding='utf-8'), ensure_ascii=False, separators=(',', ':'))
    print('amudim', len(amudim), 'summary', sum(len(a['summary']) for a in amudim), 'who', sum(len(a['who']) for a in amudim), 'quiz', sum(len(a['quiz']) for a in amudim))
